<script setup lang="ts">
/**
 * Monitor Live — V53 Real-time Dashboard
 * Same layout as Monitor2 but fed by Freqtrade WebSocket (strategy_msg) + REST API.
 * No backtest data — all values from live/dry_run bot.
 */
import { use } from 'echarts/core';
import { LineChart, CandlestickChart } from 'echarts/charts';
import { GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import VChart from 'vue-echarts';
import TradeSummary from '@/components/monitor/TradeSummary.vue';
import { coin, GROUP_A_ACTIVE, GROUP_B_ACTIVE } from '@/components/monitor/types';

use([CanvasRenderer, LineChart, CandlestickChart, GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, MarkAreaComponent, DataZoomComponent]);

// ── API (direct fetch, no botStore dependency) ──
const API_BASE = window.location.origin;
const API_USER = 'freqtrader';
const API_PASS = 'freqtrader';
let jwtToken = '';

async function apiLogin() {
  const resp = await fetch(`${API_BASE}/api/v1/token/login`, {
    method: 'POST',
    headers: { 'Authorization': 'Basic ' + btoa(API_USER + ':' + API_PASS) },
  });
  if (!resp.ok) throw new Error('Login failed');
  const data = await resp.json();
  jwtToken = data.access_token;
}

async function apiGet(endpoint: string) {
  if (!jwtToken) await apiLogin();
  const resp = await fetch(`${API_BASE}${endpoint}`, {
    headers: { 'Authorization': `Bearer ${jwtToken}` },
  });
  if (resp.status === 401) {
    await apiLogin();
    const retry = await fetch(`${API_BASE}${endpoint}`, {
      headers: { 'Authorization': `Bearer ${jwtToken}` },
    });
    return retry.json();
  }
  return resp.json();
}

// ── State ──
const connected = ref(false);
const strategyName = ref('');
const strategyTimeframe = ref('');
const lastUpdate = ref('');

// ── Live Data ──
const pairData = reactive<Record<string, any>>({});
const zHistory = reactive<Record<string, { labels: string[]; pairZ: number[]; spreadZA: number[]; spreadZB: number[] }>>({});
const btcHistory = reactive<{ labels: string[]; ohlc: number[][]; close: number[] }>({ labels: [], ohlc: [], close: [] });
const equityHistory = reactive<{ labels: string[]; values: number[] }>({ labels: [], values: [] });
const MAX_HISTORY = 200;

// ── Trade Stats from API ──
const openTrades = ref<any[]>([]);
const closedTrades = ref<any[]>([]);
const profitData = reactive({ totalProfit: 0, totalProfitPct: 0, winRate: 0, wins: 0, losses: 0, balance: 100 });

// ── Groups (from config) ──
const groupA = ref<string[]>([]);
// ── Z-Score chart pair visibility ──
const visiblePairsA = reactive<Record<string, boolean>>({});
const visiblePairsB = reactive<Record<string, boolean>>({});
const groupB = ref<string[]>([]);

// ── Activity Log ──
const activityLog = reactive<{ time: string; msg: string; color: string }[]>([]);
const MAX_LOG = 100;
const expandLog = ref(true);

function addLog(msg: string, color = '#8b949e') {
  const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  activityLog.push({ time, msg, color });
  if (activityLog.length > MAX_LOG) activityLog.shift();
}

// ── Expand/Collapse ──
const expandBtc = ref(true);
const expandZChart = ref(true);
const expandEntry = ref(true);
const expandExit = ref(true);
const expandEquity = ref(false);
const expandHistory = ref(false);

function heatColor(pct: number): string {
  const p = Math.max(0, Math.min(100, pct));
  if (p >= 100) return '#4caf50';
  if (p >= 75) return `rgb(${Math.round(255 * (1 - (p - 75) / 25) + 76 * ((p - 75) / 25))},${Math.round(213 * (1 - (p - 75) / 25) + 175 * ((p - 75) / 25))},50)`;
  if (p >= 50) return `rgb(255,${Math.round(152 + (213 - 152) * (p - 50) / 25)},50)`;
  if (p >= 25) return `rgb(248,${Math.round(81 + 71 * (p - 25) / 25)},50)`;
  return `rgb(248,${Math.round(81 * p / 25)},${Math.round(73 * (1 - p / 25) + 50 * p / 25)})`;
}
function heatBg(pct: number): string {
  return heatColor(pct).replace('rgb(', 'rgba(').replace(')', ',0.08)');
}

// ── Fetch config ──
async function fetchConfig() {
  try {
    const cfg = await apiGet('/api/v1/show_config');
    strategyName.value = (cfg.bot_name || cfg.strategy || '').replace(/_/g, ' ').replace(/ local$/i, '');
    strategyTimeframe.value = cfg.timeframe || '';
    addLog(`Connected to ${cfg.strategy} (${cfg.timeframe}) — ${cfg.state}`, '#4caf50');
    connected.value = true;
  } catch (e: any) {
    addLog(`Config fetch failed: ${e.message}`, '#f85149');
  }
}

// ── Poll REST API ──
async function pollStatus() {
  try {
    const data = await apiGet('/api/v1/status');
    const prev = openTrades.value.length;
    openTrades.value = data || [];
    const curr = openTrades.value.length;
    if (curr !== prev) {
      addLog(`Open trades: ${curr} (was ${prev})`, curr > prev ? '#4caf50' : '#ff9800');
    }
    for (const t of openTrades.value) {
      const pnl = ((t.profit_ratio || 0) * 100).toFixed(2);
      addLog(`  ${t.pair.split('/')[0]} ${t.is_short ? 'SHORT' : 'LONG'} ${pnl}% ${t.enter_tag}`, (t.profit_ratio || 0) >= 0 ? '#4caf50' : '#f85149');
    }
  } catch { /* */ }
}

async function pollProfit() {
  try {
    const p = await apiGet('/api/v1/profit');
    if (p) {
      const w = p.winning_trades || 0;
      const l = p.losing_trades || 0;
      profitData.totalProfit = p.profit_all_coin || 0;
      profitData.totalProfitPct = p.profit_all_percent || 0;
      profitData.wins = w;
      profitData.losses = l;
      profitData.winRate = (w + l) > 0 ? w / (w + l) * 100 : 0;
    }
  } catch { /* */ }
}

async function pollBalance() {
  try {
    const b = await apiGet('/api/v1/balance');
    if (b) {
      const total = b.total || 0;
      const starting = b.starting_capital || total;
      profitData.balance = total;
      // Track equity over time from real exchange balance
      const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      if (equityHistory.labels.length === 0 || equityHistory.labels[equityHistory.labels.length - 1] !== time) {
        equityHistory.labels.push(time);
        equityHistory.values.push(total);
        if (equityHistory.labels.length > MAX_HISTORY) {
          equityHistory.labels.shift();
          equityHistory.values.shift();
        }
      }
      if (!equityHistory.startingCapital) {
        (equityHistory as any).startingCapital = starting;
      }
    }
  } catch { /* */ }
}

async function pollTrades() {
  try {
    const data = await apiGet('/api/v1/trades?limit=50');
    closedTrades.value = (data?.trades || []).reverse();
  } catch { /* */ }
}

// ── Poll Pair Candles for indicators ──
async function pollCandles() {
  const allPairs = [...new Set([...groupA.value, ...groupB.value])];
  for (const pair of allPairs) {
    try {
      const resp = await apiGet(`/api/v1/pair_candles?pair=${encodeURIComponent(pair)}&timeframe=${strategyTimeframe.value || '5m'}&limit=100`);
      if (!resp?.data || !resp?.columns) continue;
      const cols = resp.columns;
      const rows = resp.data;
      if (rows.length === 0) continue;

      const lastRow = rows[rows.length - 1];
      const getCol = (name: string, row?: any) => {
        const idx = cols.indexOf(name);
        return idx >= 0 ? (row || lastRow)[idx] : null;
      };

      const coinName = coin(pair);
      const isA = groupA.value.includes(pair);

      pairData[pair] = {
        price: getCol('close'),
        pair_zscore: getCol('pair_zscore') || 0,
        spread_z_a: getCol('spread_z_a') || 0,
        spread_z_b: getCol('spread_z_b') || 0,
        vol_ratio: getCol('vol_ratio') || 1,
        vol_ok: getCol('vol_ok') || 0,
        regime_ok: getCol('regime_ok') || 1,
        rolling_corr: getCol('rolling_corr') || 0,
        spread_vol_ok: getCol('spread_vol_ok') || 1,
        btc_mom: getCol('btc_mom') || 0,
        btc_atr_z: getCol('btc_atr_z') || 0,
        btc_pump: getCol('btc_pump') || false,
        btc_dump: getCol('btc_dump') || false,
        btc_high_vol: getCol('btc_high_vol') || false,
        group: isA ? 'A' : 'B',
        coinName,
      };

      // Z history from candle history (not accumulated polls)
      const dateIdx = cols.indexOf('date');
      const pzIdx = cols.indexOf('pair_zscore');
      const szaIdx = cols.indexOf('spread_z_a');
      const szbIdx = cols.indexOf('spread_z_b');

      zHistory[pair] = { labels: [], pairZ: [], spreadZA: [], spreadZB: [] };
      const h = zHistory[pair];
      for (const row of rows) {
        const d = new Date(row[dateIdx]);
        h.labels.push(`${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`);
        h.pairZ.push(pzIdx >= 0 ? row[pzIdx] || 0 : 0);
        h.spreadZA.push(szaIdx >= 0 ? row[szaIdx] || 0 : 0);
        h.spreadZB.push(szbIdx >= 0 ? row[szbIdx] || 0 : 0);
      }
    } catch { /* */ }
  }
  // BTC candle history
  try {
    const btcPair = groupB.value.find(p => p.startsWith('BTC')) || 'BTC/USDC:USDC';
    const resp = await apiGet(`/api/v1/pair_candles?pair=${encodeURIComponent(btcPair)}&timeframe=${strategyTimeframe.value || '5m'}&limit=100`);
    if (resp?.data && resp?.columns) {
      const cols = resp.columns;
      const dateIdx = cols.indexOf('date');
      const openIdx = cols.indexOf('open');
      const highIdx = cols.indexOf('high');
      const lowIdx = cols.indexOf('low');
      const closeIdx = cols.indexOf('close');
      btcHistory.labels = [];
      btcHistory.ohlc = [];
      btcHistory.close = [];
      for (const row of resp.data) {
        const d = new Date(row[dateIdx]);
        btcHistory.labels.push(`${(d.getUTCMonth()+1)}/${d.getUTCDate()} ${d.getUTCHours().toString().padStart(2,'0')}:${d.getUTCMinutes().toString().padStart(2,'0')}`);
        btcHistory.ohlc.push([row[openIdx], row[closeIdx], row[lowIdx], row[highIdx]]);
        btcHistory.close.push(row[closeIdx]);
      }
    }
  } catch { /* */ }

  lastUpdate.value = new Date().toLocaleTimeString();

  // Log summary
  const pairs = Object.keys(pairData).filter(p => !p.startsWith('BTC'));
  if (pairs.length > 0) {
    const szA = pairData[pairs[0]]?.spread_z_a?.toFixed(2) || '?';
    const szB = pairData[pairs[0]]?.spread_z_b?.toFixed(2) || '?';
    addLog(`Poll: ${pairs.length} pairs | spread_z A=${szA} B=${szB} | ${openTrades.value.length} open`, '#666');
  }
}

// ── Z-Score Chart (live) ──
function buildLiveZChart(groupName: 'A' | 'B') {
  const groupPairs = groupName === 'A'
    ? groupA.value.filter(p => !p.startsWith('BTC'))
    : groupB.value;

  // Use first pair's history for labels and spread
  const firstPair = groupPairs.find(p => zHistory[p]?.labels?.length > 0);
  if (!firstPair) return null;

  const h = zHistory[firstPair];
  if (h.labels.length < 2) return null;

  const spreadCol = groupName === 'A' ? 'spreadZA' : 'spreadZB';
  const spreadData = h[spreadCol];
  const groupColor = groupName === 'A' ? '#4caf50' : '#b388ff';
  const pairColors = groupName === 'A'
    ? ['#4caf50', '#81c784', '#a5d6a7', '#c8e6c9']
    : ['#b388ff', '#7c4dff', '#9575cd', '#d1c4e9'];

  const visMap = groupName === 'A' ? visiblePairsA : visiblePairsB;
  const pairSeries = groupPairs.map((pair, i) => {
    const ph = zHistory[pair];
    if (!ph) return null;
    const visible = visMap[pair] !== false;
    return {
      name: coin(pair),
      type: 'line',
      data: visible ? ph.pairZ : [],
      lineStyle: { width: 1.5, opacity: visible ? 1 : 0 },
      itemStyle: { color: pairColors[i % pairColors.length] },
      symbol: 'none',
      z: 2,
    };
  }).filter(Boolean);

  return {
    animation: false,
    grid: { top: 30, right: 50, bottom: 25, left: 45 },
    tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
    legend: {
      data: ['Spread', ...groupPairs.map(p => coin(p))],
      textStyle: { color: '#666', fontFamily: 'monospace', fontSize: 10 },
      top: 0,
    },
    xAxis: {
      type: 'category',
      data: h.labels,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace', interval: Math.floor(h.labels.length / 5) },
      axisLine: { lineStyle: { color: '#21262d' } },
      splitLine: { show: false },
    },
    yAxis: {
      type: 'value',
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
      axisLine: { lineStyle: { color: '#21262d' } },
      splitLine: { lineStyle: { color: '#21262d' } },
    },
    series: [
      { name: 'Entry-', type: 'line', data: h.labels.map(() => -2.1), lineStyle: { width: 1, type: 'dashed', color: '#4caf50', opacity: 0.4 }, symbol: 'none', z: 0,
        markArea: { silent: true, itemStyle: { color: 'rgba(76,175,80,0.04)' }, data: [[{ yAxis: -2.1 }, { yAxis: -10 }]] } },
      { name: 'Entry+', type: 'line', data: h.labels.map(() => 2.1), lineStyle: { width: 1, type: 'dashed', color: '#f85149', opacity: 0.4 }, symbol: 'none', z: 0,
        markArea: { silent: true, itemStyle: { color: 'rgba(248,81,73,0.04)' }, data: [[{ yAxis: 2.1 }, { yAxis: 10 }]] } },
      { name: 'Zero', type: 'line', data: h.labels.map(() => 0), lineStyle: { width: 1, type: 'dotted', color: '#30363d' }, symbol: 'none', z: 0 },
      { name: 'Spread', type: 'line', data: spreadData, lineStyle: { width: 2, color: '#ffd54f' }, itemStyle: { color: '#ffd54f' }, symbol: 'none', z: 3,
        areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [{ offset: 0, color: 'rgba(255,213,79,0.1)' }, { offset: 0.5, color: 'rgba(255,213,79,0)' }, { offset: 1, color: 'rgba(255,213,79,0.1)' }] } } },
      ...pairSeries,
    ],
  };
}

const liveZChartA = computed(() => buildLiveZChart('A'));
const liveZChartB = computed(() => buildLiveZChart('B'));

// ── BTC Chart ──
const liveBtcChart = computed(() => {
  if (btcHistory.labels.length < 2) return null;
  return {
    animation: false,
    grid: { top: 10, right: 50, bottom: 25, left: 60 },
    tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
    xAxis: {
      type: 'category', data: btcHistory.labels,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace', interval: Math.floor(btcHistory.labels.length / 5) },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { show: false },
    },
    yAxis: {
      type: 'value', scale: true,
      axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
      axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { lineStyle: { color: '#21262d' } },
    },
    series: [{
      type: 'candlestick', data: btcHistory.ohlc,
      itemStyle: { color: '#4caf50', color0: '#f85149', borderColor: '#4caf50', borderColor0: '#f85149' },
    }],
  };
});

// ── Equity Curve ──
const liveEquityChart = computed(() => {
  if (equityHistory.values.length < 2) return null;
  const initial = (equityHistory as any).startingCapital || equityHistory.values[0] || 100;
  const current = equityHistory.values[equityHistory.values.length - 1] || initial;
  const profit = current - initial;
  return {
    option: {
      animation: false,
      grid: { top: 10, right: 50, bottom: 25, left: 60 },
      tooltip: { trigger: 'axis', backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontFamily: 'monospace', fontSize: 11 } },
      xAxis: {
        type: 'category', data: equityHistory.labels,
        axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
        axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { show: false },
      },
      yAxis: {
        type: 'value', scale: true,
        axisLabel: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
        axisLine: { lineStyle: { color: '#21262d' } }, splitLine: { lineStyle: { color: '#21262d' } },
      },
      series: [{
        type: 'line', data: equityHistory.values, symbol: 'none',
        lineStyle: { width: 2, color: profit >= 0 ? '#4caf50' : '#f85149' },
        areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [{ offset: 0, color: profit >= 0 ? 'rgba(76,175,80,0.15)' : 'rgba(248,81,73,0.15)' }, { offset: 1, color: 'rgba(0,0,0,0)' }] } },
      }],
    },
    current, profit, profitPct: ((current / initial - 1) * 100).toFixed(1),
  };
});

// ── Entry Conditions ──
const entryConditions = computed(() => {
  const tradablePairs = Object.keys(pairData).filter(p => !p.startsWith('BTC'));
  const result: any[] = [];

  for (const pair of tradablePairs) {
    const d = pairData[pair];
    if (!d) continue;
    const isA = groupA.value.includes(pair);
    const sz = isA ? d.spread_z_a : d.spread_z_b;
    const pz = d.pair_zscore;
    // 7. Pair Free — no active trade on this pair
    const pairHasTrade = openTrades.value.some(t => t.pair === pair);

    // 8. Group Balance — check imbalance between groups
    let countA = 0, countB = 0;
    for (const t of openTrades.value) {
      if (groupA.value.includes(t.pair)) countA++;
      else countB++;
    }
    const maxImbalance = 2;
    const wouldImbalance = isA ? (countA + 1 - countB > maxImbalance) : (countB + 1 - countA > maxImbalance);

    // 9. Cooldown — 24h block after catastrophic loss
    let inCooldown = false;
    let cooldownDetail = 'no recent loss';
    const now = Date.now();
    const cooldownMs = 24 * 60 * 60 * 1000;
    for (const t of closedTrades.value) {
      const exitReason = t.exit_reason || '';
      const isCatastrophic = exitReason === 'stop_loss' || exitReason === 'stoploss' || exitReason.startsWith('mkt_stop') || (exitReason === 'no_reversion' && (t.profit_ratio || 0) < -0.03);
      if (isCatastrophic && t.close_date) {
        const closeTime = new Date(t.close_date).getTime();
        if (now - closeTime < cooldownMs) {
          inCooldown = true;
          const remainH = ((cooldownMs - (now - closeTime)) / 3600000).toFixed(1);
          cooldownDetail = `${t.pair?.split('/')[0]} ${exitReason} — ${remainH}h left`;
          break;
        }
      }
    }

    const conditions = [
      { name: 'Spread Z', ok: Math.abs(sz) >= 2.1, value: `${sz?.toFixed(3)}σ`, pct: Math.min(100, (Math.abs(sz) / 2.1) * 100) },
      { name: 'Pair Z', ok: Math.abs(pz) >= 1.2, value: `${pz?.toFixed(3)}σ`, pct: Math.min(100, (Math.abs(pz) / 1.2) * 100) },
      { name: 'Volume', ok: d.vol_ok === 1, value: `${d.vol_ratio?.toFixed(1)}x`, pct: d.vol_ok ? 100 : Math.min(99, d.vol_ratio * 100) },
      { name: 'Regime', ok: d.regime_ok === 1, value: d.regime_ok ? 'RANGING' : 'FAIL', pct: d.regime_ok ? 100 : 0 },
      { name: 'Spread Vol', ok: d.spread_vol_ok === 1, value: d.spread_vol_ok ? 'OK' : 'ERRATIC', pct: d.spread_vol_ok ? 100 : 0 },
      { name: 'BTC Safe', ok: !d.btc_pump && !d.btc_dump && !d.btc_high_vol, value: d.btc_high_vol ? 'CHAOS' : d.btc_pump ? 'PUMP' : d.btc_dump ? 'DUMP' : 'OK', pct: (!d.btc_pump && !d.btc_dump && !d.btc_high_vol) ? 100 : 0 },
      { name: 'Pair Free', ok: !pairHasTrade, value: pairHasTrade ? 'IN TRADE' : 'Free', pct: pairHasTrade ? 0 : 100 },
      { name: 'Balance', ok: !wouldImbalance, value: `A:${countA} B:${countB}`, pct: wouldImbalance ? 0 : 100 },
      { name: 'Cooldown', ok: !inCooldown, value: inCooldown ? 'ACTIVE' : 'Clear', pct: inCooldown ? 0 : 100 },
    ];
    const score = conditions.filter(c => c.ok).length;
    const isActive = isA ? GROUP_A_ACTIVE.includes(pair) : GROUP_B_ACTIVE.includes(pair);
    // Direction: negative spread_z = LONG, positive = SHORT
    const direction = sz < 0 ? 'LONG' : sz > 0 ? 'SHORT' : 'NEUTRAL';
    result.push({
      pair, coinName: d.coinName, group: d.group,
      color: isA ? '#4caf50' : '#b388ff',
      conditions, score, total: conditions.length,
      isActive, direction,
    });
  }
  return result;
});

// ── Trade History computed stats ──
const historyTotals = computed(() => {
  const trades = closedTrades.value.filter(t => !t.is_open);
  const total = trades.length;
  const wins = trades.filter(t => (t.profit_ratio || 0) >= 0).length;
  const losses = total - wins;
  const profits = trades.map(t => (t.profit_ratio || 0) * 100);
  const totalProfit = profits.reduce((a, b) => a + b, 0).toFixed(2);
  const avgProfit = total > 0 ? (profits.reduce((a, b) => a + b, 0) / total).toFixed(2) : '0.00';
  const best = total > 0 ? Math.max(...profits).toFixed(2) : '0.00';
  const worst = total > 0 ? Math.min(...profits).toFixed(2) : '0.00';
  const durations = trades.map(t => t.trade_duration || 0);
  const avgDuration = total > 0 ? Math.round(durations.reduce((a, b) => a + b, 0) / total) : 0;
  return { total, wins, losses, totalProfit, avgProfit, best, worst, avgDuration };
});

function fmtDate(dateStr: string): string {
  if (!dateStr) return '-';
  const d = new Date(dateStr);
  const mo = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${mo}/${dd} ${hh}:${mm}`;
}

// ── Polling intervals ──
let pollTimer: number | null = null;

onMounted(async () => {
  await fetchConfig();

  // Try to get groups from bot controller
  try {
    const CTRL = `${window.location.protocol}//${window.location.hostname}:8084`;
    const resp = await fetch(`${CTRL}/status`);
    const data = await resp.json();
    // Fallback: hardcode V53 groups
  } catch { /* */ }

  // Default groups (V53)
  // Group A: XRP+ADA (sub1) vs SOL+LINK (sub2) — only XRP trades (LONG)
  // Group B: BTC+SOL (sub1) vs ETH (sub2) — all trade (LONG+SHORT)
  if (!groupA.value.length) {
    const suffix = strategyName.value.includes('USDT') ? 'USDT:USDT' : 'USDC:USDC';
    groupA.value = [`XRP/${suffix}`, `ADA/${suffix}`, `SOL/${suffix}`, `LINK/${suffix}`];
    groupB.value = [`BTC/${suffix}`, `SOL/${suffix}`, `ETH/${suffix}`];
  }
  // Init visibility (all visible by default)
  for (const p of groupA.value) { if (!(p in visiblePairsA)) visiblePairsA[p] = true; }
  for (const p of groupB.value) { if (!(p in visiblePairsB)) visiblePairsB[p] = true; }

  // Initial poll
  await pollStatus();
  await pollProfit();
  await pollBalance();
  await pollTrades();
  await pollCandles();

  // Poll every 30s (one candle of 5m = 300s, poll 10x per candle)
  pollTimer = window.setInterval(async () => {
    await pollCandles();
    await pollStatus();
    await pollProfit();
    await pollBalance();
  }, 30000);

  // Trades less frequently
  window.setInterval(pollTrades, 60000);
});

onUnmounted(() => {
  if (pollTimer) clearInterval(pollTimer);
});
</script>

